static void GIMP_UnboundSlot(void)
{
    Com_Error( ERR_DROP, "module called an game_import_t import slot that no engine implementation is bound to (see init log for the slot list)" );
}
static void GIMP_VerifyBound( game_import_t *t )
{
    size_t i;
    for ( i = 0; i < ARRAY_LEN( GIMP_slots ); i++ ) {
        if ( *( void ** )( ( char * )t + GIMP_slots[ i ].off ) == NULL ) {
            *( void ** )( ( char * )t + GIMP_slots[ i ].off ) = ( void * )GIMP_UnboundSlot;
            Com_DPrintf( "game_import_t slot %s is not backed by this engine yet; calls will error\n", GIMP_slots[ i ].name );
        }
    }
}
